// native/core/qrss/simfile against channel.load_npz: the pins
// (simfile_pins.hpp, generated by gen_simfile_pins.py) are small files in
// qrss_simulate.py's .npz form and broken ones, each with what the
// reference makes of it -- the receiver's part of the Sim, or the
// exception's class and str(). Two files the reference reads are refused
// here on purpose (simfile.hpp): complex128 fe, and np.savez_compressed.

#include <bit>
#include <complex>
#include <cstdint>
#include <cstdio>
#include <exception>
#include <iterator>
#include <string>
#include <vector>

#include "qrss/simfile.hpp"
#include "qrss_check.hpp"
#include "simfile_pins.hpp"

using namespace sstvae;
namespace simfile = sstvae::qrss::simfile;

static std::vector<std::uint8_t> unhex(const char* const* lines, std::size_t n) {
    std::vector<std::uint8_t> out;
    const auto nib = [](char c) -> unsigned {
        return c <= '9' ? static_cast<unsigned>(c - '0') : static_cast<unsigned>(c - 'a' + 10);
    };
    for (std::size_t i = 0; i < n; ++i)
        for (const char* p = lines[i]; p[0] != '\0' && p[1] != '\0'; p += 2)
            out.push_back(static_cast<std::uint8_t>(nib(p[0]) << 4 | nib(p[1])));
    return out;
}

// The port's own refusals of files the reference reads.
struct Deviation {
    const char* name;
    const char* cls;
    const char* msg;
};
static const Deviation DEVIATIONS[] = {
    {"fe_c16", "ValueError",
     "simfile: fe is <c16 of 1 dimensions, not complex64 (n,) as qrss_simulate.py writes it"},
    {"compressed", "zipfile.BadZipFile",
     "simfile: member fe.npy is compressed (np.savez_compressed), which is not read here"},
};

static void test_pins() {
    for (const simfile_pins::Pin& pin : simfile_pins::PINS) {
        const std::string what = pin.name;
        const std::vector<std::uint8_t> file = unhex(pin.hex, pin.n_hex);
        const Deviation* dev = nullptr;
        for (const Deviation& d : DEVIATIONS)
            if (what == d.name) dev = &d;
        const bool ok = pin.ok && dev == nullptr;
        const std::string cls = dev ? dev->cls : pin.cls ? pin.cls : "";
        const std::string msg = dev ? dev->msg : pin.msg ? pin.msg : "";
        try {
            const simfile::Sim sim = simfile::parse(file);
            if (!ok) {
                check::fail(what, "read, where the reference raises " + cls + ": " + msg);
                continue;
            }
            check::equal(sim.fs, pin.fs, what + " fs");
            check::equal(std::bit_cast<std::uint64_t>(sim.t0_index), std::bit_cast<std::uint64_t>(pin.t0_index),
                         what + " t0_index, bitwise");
            check::equal(sim.q, pin.q, what + " q");
            check::equal(sim.frame, std::string(pin.frame), what + " frame");
            check::equal(sim.fe.size(), pin.n_fe, what + " fe size");
            bool same = sim.fe.size() == pin.n_fe;
            for (std::size_t i = 0; same && i < pin.n_fe; ++i)
                same = std::bit_cast<std::uint32_t>(sim.fe[i].real()) ==
                           std::bit_cast<std::uint32_t>(pin.fe[2 * i]) &&
                       std::bit_cast<std::uint32_t>(sim.fe[i].imag()) ==
                           std::bit_cast<std::uint32_t>(pin.fe[2 * i + 1]);
            check::is_true(same, what + " fe, bitwise");
        } catch (const simfile::Error& e) {
            if (ok) {
                check::fail(what, std::string("refused: ") + e.cls() + ": " + e.what());
                continue;
            }
            check::equal(e.cls(), cls, what + " class");
            check::equal(std::string(e.what()), msg, what + " message");
        }
    }
}

// Damaged archives: refused with zipfile's class (the text is this port's).
static void test_damage() {
    const auto& pin = simfile_pins::PINS[0];
    std::vector<std::uint8_t> file = unhex(pin.hex, pin.n_hex);
    // One flipped byte in a member's data: the CRC refuses it.
    std::vector<std::uint8_t> bad = file;
    bad[200] ^= 0x01;
    try {
        simfile::parse(bad);
        check::fail("flipped byte", "read");
    } catch (const simfile::Error& e) {
        check::equal(e.cls(), std::string("zipfile.BadZipFile"), "flipped byte class");
    }
    // Cut short: no end record.
    std::vector<std::uint8_t> cut(file.begin(), file.begin() + static_cast<std::ptrdiff_t>(file.size() / 2));
    try {
        simfile::parse(cut);
        check::fail("truncated", "read");
    } catch (const simfile::Error& e) {
        check::equal(e.cls(), std::string("zipfile.BadZipFile"), "truncated class");
    }
    // Bytes before the archive: np.load looks at the first six bytes only,
    // so this is the pickle refusal, not zipfile's tolerance of a prefix.
    std::vector<std::uint8_t> prefixed = {'#', '!', '\n'};
    prefixed.insert(prefixed.end(), file.begin(), file.end());
    try {
        simfile::parse(prefixed);
        check::fail("prefixed archive", "read");
    } catch (const simfile::Error& e) {
        check::equal(e.cls(), std::string("ValueError"), "prefixed archive class");
    }
    // load(): a missing file is the caller's (std::runtime_error).
    try {
        simfile::load("/nonexistent/qrss/simfile.npz");
        check::fail("missing file", "read");
    } catch (const simfile::Error&) {
        check::fail("missing file", "a simfile::Error");
    } catch (const std::runtime_error&) {
        check::is_true(true, "missing file");
    }
}

int main() {
    try {
        test_pins();
        test_damage();
    } catch (const std::exception& e) {
        std::fprintf(stderr, "FATAL: %s\n", e.what());
        return 1;
    }
    return check::report("qrss_simfile");
}
